Definition mk_1RB1RB_0LC0RD_1RA1LC_0LA1RB (w : Sym) (d : Dir) (n : St) : option Trans := Some (mkTrans w d n).
Local Notation mk := mk_1RB1RB_0LC0RD_1RA1LC_0LA1RB.

(** 1RB1RB_0LC0RD_1RA1LC_0LA1RB *)
Definition tm_1RB1RB_0LC0RD_1RA1LC_0LA1RB : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB | StA, S1 => mk S1 DR StB
  | StB, S0 => mk S0 DL StC | StB, S1 => mk S0 DR StD
  | StC, S0 => mk S1 DR StA | StC, S1 => mk S1 DL StC
  | StD, S0 => mk S0 DL StA | StD, S1 => mk S1 DR StB end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_1RB1RB_0LC0RD_1RA1LC_0LA1RB : list Instr := [].
Definition tmw_1RB1RB_0LC0RD_1RA1LC_0LA1RB : TM := tm_wrap_trs tm_1RB1RB_0LC0RD_1RA1LC_0LA1RB pins_1RB1RB_0LC0RD_1RA1LC_0LA1RB.
Local Notation tm := tmw_1RB1RB_0LC0RD_1RA1LC_0LA1RB.

Definition Cc_1RB1RB_0LC0RD_1RA1LC_0LA1RB (p : positive) : cconf := (StB, (Ap_Alph_10_11_11 p ++ [S0], S0, [])).
