(** ** The certificate *)

(** j = 0: the repeated block is absent, so the whole lap is concrete. *)
Definition Z0_1RB1RB_0LC0RD_1RA1LC_0LA1RB : sconf := mkC StB (mkS [S1;S0] [] 0 0 []) S0 (mkS [] [] 0 0 []).
Definition Z1_1RB1RB_0LC0RD_1RA1LC_0LA1RB : sconf := mkC StB (mkS [S1;S1] [] 0 0 []) S0 (mkS [] [] 0 0 []).
Definition chz_1RB1RB_0LC0RD_1RA1LC_0LA1RB : list lstep := [SWin 4].

Lemma run_z_1RB1RB_0LC0RD_1RA1LC_0LA1RB : srun tm false true chz_1RB1RB_0LC0RD_1RA1LC_0LA1RB Z0_1RB1RB_0LC0RD_1RA1LC_0LA1RB = Some (Z1_1RB1RB_0LC0RD_1RA1LC_0LA1RB, 0, 4).
