Local Notation Cin := Cin_1RB1RB_0LC0RD_1RA1LC_0LA1RB.

(** [E (2^n) = A^n C]: the value this family's count starts at. *)
Lemma epow2_1RB1RB_0LC0RD_1RA1LC_0LA1RB : forall n, Ip (pow2 n) = rep [S1;S0] n ++ [S1].
Proof. induction n; simpl; [reflexivity | rewrite IHn; reflexivity]. Qed.

(** Its own INTERIOR lap -- ordinary and affine.  Iterating it to the fill is
    where a [Theta(2^j)] lives, and [inner_to_fill_lift] keeps it inside an
    existential. *)
Definition AI0_1RB1RB_0LC0RD_1RA1LC_0LA1RB : sconf := mkC StA (mkS [] [S1;S1] 1 0 [S1;S0]) S0 (mkS [] [] 0 0 []).
Definition AI1_1RB1RB_0LC0RD_1RA1LC_0LA1RB : sconf := mkC StA (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [S0] [] 0 0 []).
Definition chn_1RB1RB_0LC0RD_1RA1LC_0LA1RB : list lstep := [SWinR 2; SCycL 2 0; SWin 4; SCycR 2; SWin 2].

Lemma run_inner_1RB1RB_0LC0RD_1RA1LC_0LA1RB : srun tm false true chn_1RB1RB_0LC0RD_1RA1LC_0LA1RB AI0_1RB1RB_0LC0RD_1RA1LC_0LA1RB = Some (AI1_1RB1RB_0LC0RD_1RA1LC_0LA1RB, 4, 8).
Proof. vm_compute. reflexivity. Qed.

(** *** boot: the outer overflow anchor -> the first inner anchor at [pow2 j] *)
