(** *** exit: the last inner all-ones fill -> the outer successor *)
Definition BE0_1RB1RB_0LC0RD_1RA1LC_0LA1RB : sconf := mkC StA (mkS [] [S1;S1] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 []).
Definition che_1RB1RB_0LC0RD_1RA1LC_0LA1RB : list lstep := [SWinR 2; SCycL 2 0; SWin 2; SWinL 4; SCycR 2; SWin 1; SRotL 1; SFoldL 1].

Lemma run_exit_1RB1RB_0LC0RD_1RA1LC_0LA1RB : srun tm true true che_1RB1RB_0LC0RD_1RA1LC_0LA1RB BE0_1RB1RB_0LC0RD_1RA1LC_0LA1RB = Some (B1_1RB1RB_0LC0RD_1RA1LC_0LA1RB, 4, 9).
