(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_1RB1RB_0LC0RD_1RA1LC_0LA1RB : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] 0 Z0_1RB1RB_0LC0RD_1RA1LC_0LA1RB /\
  cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] 0 Z1_1RB1RB_0LC0RD_1RA1LC_0LA1RB = Cc (Pos.succ p).
Proof.
  intros p q0 E. destruct (Alph_10_11_11.cview_some_Alph_10_11_11 p 0 q0 E) as (H1 & H2).
  unfold Cc_1RB1RB_0LC0RD_1RA1LC_0LA1RB, cden, Z0_1RB1RB_0LC0RD_1RA1LC_0LA1RB, Z1_1RB1RB_0LC0RD_1RA1LC_0LA1RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gp_1RB1RB_0LC0RD_1RA1LC_0LA1RB : forall p j q0, cview p = (S j, Some q0) ->
  Cc p = cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j P0_1RB1RB_0LC0RD_1RA1LC_0LA1RB /\
  cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j P1_1RB1RB_0LC0RD_1RA1LC_0LA1RB = Cc (Pos.succ p).
Proof.
  intros p j q0 E. destruct (Alph_10_11_11.cview_some_Alph_10_11_11 p (S j) q0 E) as (H1 & H2).
  unfold Cc_1RB1RB_0LC0RD_1RA1LC_0LA1RB, cden, P0_1RB1RB_0LC0RD_1RA1LC_0LA1RB, P1_1RB1RB_0LC0RD_1RA1LC_0LA1RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_1RB1RB_0LC0RD_1RA1LC_0LA1RB : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct j as [|j'].
  - destruct (gz_1RB1RB_0LC0RD_1RA1LC_0LA1RB p q0 E) as (HA & HB).
    exists (0 * 0 + 4). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chz_1RB1RB_0LC0RD_1RA1LC_0LA1RB Z0_1RB1RB_0LC0RD_1RA1LC_0LA1RB Z1_1RB1RB_0LC0RD_1RA1LC_0LA1RB 0 4
               run_z_1RB1RB_0LC0RD_1RA1LC_0LA1RB (Ap_Alph_10_11_11 q0 ++ [S0]) [] 0
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
  - destruct (gp_1RB1RB_0LC0RD_1RA1LC_0LA1RB p j' q0 E) as (HA & HB).
    exists (4 * j' + 8). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_1RB1RB_0LC0RD_1RA1LC_0LA1RB P0_1RB1RB_0LC0RD_1RA1LC_0LA1RB P1_1RB1RB_0LC0RD_1RA1LC_0LA1RB 4 8
               run_p_1RB1RB_0LC0RD_1RA1LC_0LA1RB (Ap_Alph_10_11_11 q0 ++ [S0]) [] j'
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
Qed.

Lemma gso_1RB1RB_0LC0RD_1RA1LC_0LA1RB : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB1RB_0LC0RD_1RA1LC_0LA1RB.
Proof.
  intros p j E. destruct (Alph_10_11_11.cview_none_Alph_10_11_11 p j E) as (H1 & _).
  unfold Cc_1RB1RB_0LC0RD_1RA1LC_0LA1RB, cden, B0_1RB1RB_0LC0RD_1RA1LC_0LA1RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_1RB1RB_0LC0RD_1RA1LC_0LA1RB : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB1RB_0LC0RD_1RA1LC_0LA1RB : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1RB_0LC0RD_1RA1LC_0LA1RB) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (Alph_10_11_11.cview_none_Alph_10_11_11 p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB1RB_0LC0RD_1RA1LC_0LA1RB
             = (StB, (rep [S1;S0] (S j) ++ [S1;S1], S0, []))).
  { unfold cden, B1_1RB1RB_0LC0RD_1RA1LC_0LA1RB, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StB, ((rep [S1;S0] (S j) ++ [S1;S1]) ++ [S0], S0, []))).
  { unfold Cc_1RB1RB_0LC0RD_1RA1LC_0LA1RB. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lbl_1RB1RB_0LC0RD_1RA1LC_0LA1RB. reflexivity.
Qed.

Lemma gsn_1RB1RB_0LC0RD_1RA1LC_0LA1RB : forall v i q0, cview v = (i, Some q0) ->
  Cin v = cden (Ip q0 ++ [S1]) [] i AI0_1RB1RB_0LC0RD_1RA1LC_0LA1RB.
Proof.
  intros v i q0 E. destruct (ILCounter.cview_some_I v i q0 E) as (H1 & _).
  unfold Cin_1RB1RB_0LC0RD_1RA1LC_0LA1RB, cden, AI0_1RB1RB_0LC0RD_1RA1LC_0LA1RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S1] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gen_1RB1RB_0LC0RD_1RA1LC_0LA1RB : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Ip q0 ++ [S1]) [] i AI1_1RB1RB_0LC0RD_1RA1LC_0LA1RB) = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E. destruct (ILCounter.cview_some_I v i q0 E) as (_ & H2).
  unfold Cin_1RB1RB_0LC0RD_1RA1LC_0LA1RB, cden, AI1_1RB1RB_0LC0RD_1RA1LC_0LA1RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  replace (0 * i + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  change ([S0]) with (([]) ++ [S0]).
  rewrite !lift_app_blank.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S0] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapin_1RB1RB_0LC0RD_1RA1LC_0LA1RB : forall v i q0, cview v = (i, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cin v) = Some c'
               /\ lift c' = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E.
  exists (4 * i + 8), (cden (Ip q0 ++ [S1]) [] i AI1_1RB1RB_0LC0RD_1RA1LC_0LA1RB).
  split; [lia|]. split; [| exact (gen_1RB1RB_0LC0RD_1RA1LC_0LA1RB v i q0 E)].
  rewrite (gsn_1RB1RB_0LC0RD_1RA1LC_0LA1RB v i q0 E).
  exact (srun_sound tm false true chn_1RB1RB_0LC0RD_1RA1LC_0LA1RB AI0_1RB1RB_0LC0RD_1RA1LC_0LA1RB AI1_1RB1RB_0LC0RD_1RA1LC_0LA1RB 4 8
           run_inner_1RB1RB_0LC0RD_1RA1LC_0LA1RB (Ip q0 ++ [S1]) [] i
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

(** The chain into this family lands on its anchor up to 0/1
    trailing blanks. *)
Lemma gbo_1RB1RB_0LC0RD_1RA1LC_0LA1RB : forall j, lift (cden [] [] j BB1_1RB1RB_0LC0RD_1RA1LC_0LA1RB) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_1RB1RB_0LC0RD_1RA1LC_0LA1RB = (StA, (rep [S1;S0] j ++ [S1;S1], S0, ([]) ++ [S0]))).
  { unfold cden, BB1_1RB1RB_0LC0RD_1RA1LC_0LA1RB, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StA, (rep [S1;S0] j ++ [S1;S1], S0, []))).
  { unfold Cin_1RB1RB_0LC0RD_1RA1LC_0LA1RB. rewrite epow2_1RB1RB_0LC0RD_1RA1LC_0LA1RB.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_1RB1RB_0LC0RD_1RA1LC_0LA1RB. rewrite ?lift_app_blank. reflexivity.
Qed.

(** This family's all-ones fill IS the next chain's start.  [cview (fill
    (pow2 j)) = (S j, None)] ([NestedLapLift.cview_fill_pow2]), so the
    family's own overflow decomposition names the word. *)
Lemma gxi_1RB1RB_0LC0RD_1RA1LC_0LA1RB : forall j, Cin (fill (pow2 j)) = cden [] [] j BE0_1RB1RB_0LC0RD_1RA1LC_0LA1RB.
Proof.
  intro j.
  destruct (ILCounter.cview_none_I (fill (pow2 j)) j (cview_fill_pow2 j)) as (H1 & _).
  unfold Cin_1RB1RB_0LC0RD_1RA1LC_0LA1RB, cden, BE0_1RB1RB_0LC0RD_1RA1LC_0LA1RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- ?app_assoc; cbn [app];
        rewrite ?app_nil_r; reflexivity | reflexivity ].
Qed.

(** The interior lap, restated up to [lift] -- what [vis_via_ovf_lift] and
    [vis_via_fill] consume. *)
Lemma lapil_1RB1RB_0LC0RD_1RA1LC_0LA1RB : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. intros p j q0 E. destruct (lapi_1RB1RB_0LC0RD_1RA1LC_0LA1RB p j q0 E) as (n & Hn & Hr).
  exists n, (Cc (Pos.succ p)).
  split; [exact Hn | split; [exact Hr | reflexivity]]. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_1RB1RB_0LC0RD_1RA1LC_0LA1RB : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_1RB1RB_0LC0RD_1RA1LC_0LA1RB p (pow2 j)).
  - exists (4 * j + 7), (cden [] [] j BB1_1RB1RB_0LC0RD_1RA1LC_0LA1RB).
    split; [lia|]. split; [| exact (gbo_1RB1RB_0LC0RD_1RA1LC_0LA1RB j)].
    rewrite (gso_1RB1RB_0LC0RD_1RA1LC_0LA1RB p j E).
    exact (srun_sound tm true true chb_1RB1RB_0LC0RD_1RA1LC_0LA1RB B0_1RB1RB_0LC0RD_1RA1LC_0LA1RB BB1_1RB1RB_0LC0RD_1RA1LC_0LA1RB 4 7
             run_boot_1RB1RB_0LC0RD_1RA1LC_0LA1RB [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (4 * j + 9), (cden [] [] j B1_1RB1RB_0LC0RD_1RA1LC_0LA1RB).
    split; [| exact (geo_1RB1RB_0LC0RD_1RA1LC_0LA1RB p j E)].
    rewrite (gxi_1RB1RB_0LC0RD_1RA1LC_0LA1RB j).
