(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_1RB1RB_0LC0RD_1RD1LC_0LC1RA : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Ap_Alph_011_111_1 q0 ++ [S0]) [] 0 Z0_1RB1RB_0LC0RD_1RD1LC_0LC1RA /\
  cden (Ap_Alph_011_111_1 q0 ++ [S0]) [] 0 Z1_1RB1RB_0LC0RD_1RD1LC_0LC1RA = Cc (Pos.succ p).
Proof.
  intros p q0 E. destruct (Alph_011_111_1.cview_some_Alph_011_111_1 p 0 q0 E) as (H1 & H2).
  unfold Cc_1RB1RB_0LC0RD_1RD1LC_0LC1RA, cden, Z0_1RB1RB_0LC0RD_1RD1LC_0LC1RA, Z1_1RB1RB_0LC0RD_1RD1LC_0LC1RA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gp_1RB1RB_0LC0RD_1RD1LC_0LC1RA : forall p j q0, cview p = (S j, Some q0) ->
  Cc p = cden (Ap_Alph_011_111_1 q0 ++ [S0]) [] j P0_1RB1RB_0LC0RD_1RD1LC_0LC1RA /\
  cden (Ap_Alph_011_111_1 q0 ++ [S0]) [] j P1_1RB1RB_0LC0RD_1RD1LC_0LC1RA = Cc (Pos.succ p).
Proof.
  intros p j q0 E. destruct (Alph_011_111_1.cview_some_Alph_011_111_1 p (S j) q0 E) as (H1 & H2).
  unfold Cc_1RB1RB_0LC0RD_1RD1LC_0LC1RA, cden, P0_1RB1RB_0LC0RD_1RD1LC_0LC1RA, P1_1RB1RB_0LC0RD_1RD1LC_0LC1RA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_1RB1RB_0LC0RD_1RD1LC_0LC1RA : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct j as [|j'].
  - destruct (gz_1RB1RB_0LC0RD_1RD1LC_0LC1RA p q0 E) as (HA & HB).
    exists (0 * 0 + 2). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chz_1RB1RB_0LC0RD_1RD1LC_0LC1RA Z0_1RB1RB_0LC0RD_1RD1LC_0LC1RA Z1_1RB1RB_0LC0RD_1RD1LC_0LC1RA 0 2
               run_z_1RB1RB_0LC0RD_1RD1LC_0LC1RA (Ap_Alph_011_111_1 q0 ++ [S0]) [] 0
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
