    exists (6 * j' + 8). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_1RB1RB_0LC0RD_1RD1LC_0LC1RA P0_1RB1RB_0LC0RD_1RD1LC_0LC1RA P1_1RB1RB_0LC0RD_1RD1LC_0LC1RA 6 8
               run_p_1RB1RB_0LC0RD_1RD1LC_0LC1RA (Ap_Alph_011_111_1 q0 ++ [S0]) [] j'
               ltac:(discriminate) ltac:(reflexivity)).
