Qed.

Lemma gso_1RB1RB_0LC0RD_1RD1LC_0LC1RA : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB1RB_0LC0RD_1RD1LC_0LC1RA.
