Qed.

Lemma lbl_1RB1RB_0LC0RD_1RD1LC_0LC1RA : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB1RB_0LC0RD_1RD1LC_0LC1RA : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1RB_0LC0RD_1RD1LC_0LC1RA) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (Alph_011_111_1.cview_none_Alph_011_111_1 p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB1RB_0LC0RD_1RD1LC_0LC1RA
