    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB1RB_0LC0RD_1RD1LC_0LC1RA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1RB_0LC0RD_1RD1LC_0LC1RA = Some t ->
  forall p j, cview p = (S j, None) ->
