(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB1RB_0LC0RD_1RD1LC_0LC1RA : forall t, ~ In t pins_1RB1RB_0LC0RD_1RD1LC_0LC1RA ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB1RB_0LC0RD_1RD1LC_0LC1RA.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_1RB1RB_0LC0RD_1RD1LC_0LC1RA
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 2; SCycR 3; SWin 1]).
    vm_compute; reflexivity.
  - (* A1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1RB_0LC0RD_1RD1LC_0LC1RA (StA, S1)).
    intros p1 j1 E1.
    exact (firex_1RB1RB_0LC0RD_1RD1LC_0LC1RA [SRotL 1; SWin 1; SCycL 3 0; SWin 2; SWinL 3] (StA, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB1RB_0LC0RD_1RD1LC_0LC1RA
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 2; SCycR 3; SWin 1; SWinR 1]).
    vm_compute; reflexivity.
  - (* B1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1RB_0LC0RD_1RD1LC_0LC1RA (StB, S1)).
    intros p1 j1 E1.
    exact (firex_1RB1RB_0LC0RD_1RD1LC_0LC1RA [SRotL 1; SWin 1; SCycL 3 0; SWin 2; SWinL 4] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB1RB_0LC0RD_1RD1LC_0LC1RA
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 1]).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB1RB_0LC0RD_1RD1LC_0LC1RA
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB1RB_0LC0RD_1RD1LC_0LC1RA
      with (l := []).
    vm_compute; reflexivity.
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_1RB1RB_0LC0RD_1RD1LC_0LC1RA
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 2]).
    vm_compute; reflexivity.
Qed.

Theorem nqhtr_1RB1RB_0LC0RD_1RD1LC_0LC1RA : NeverQuasiHaltsTr tm_1RB1RB_0LC0RD_1RD1LC_0LC1RA.
Proof.
  apply (glue_neverqhtr tm_1RB1RB_0LC0RD_1RD1LC_0LC1RA pins_1RB1RB_0LC0RD_1RD1LC_0LC1RA Cc 2).
