  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1RB_0LC0RD_1RD1LC_1LC1RA B0_1RB1RB_0LC0RD_1RD1LC_1LC1RA B1_1RB1RB_0LC0RD_1RD1LC_1LC1RA 6 18 p j' [] []).
    + exact run_ovf_1RB1RB_0LC0RD_1RD1LC_1LC1RA.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1RB_0LC0RD_1RD1LC_1LC1RA p j' E).
    + exact (geo_1RB1RB_0LC0RD_1RD1LC_1LC1RA p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma boot_1RB1RB_0LC0RD_1RD1LC_1LC1RA : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
