(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB1RB_0LC1RA_1LD0RB_1RB1LC : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Jp q0 ++ [S1;S0]) [] j A0_1RB1RB_0LC1RA_1LD0RB_1RB1LC.
