    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB1RB_0LC1RA_1RC1LD_1LC0RA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1RB_0LC1RA_1RC1LD_1LC0RA = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB1RB_0LC1RA_1RC1LD_1LC0RA p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1RB_0LC1RA_1RC1LD_1LC0RA p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB1RB_0LC1RA_1RC1LD_1LC0RA : forall t, ~ In t pins_1RB1RB_0LC1RA_1RC1LD_1LC0RA ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB1RB_0LC1RA_1RC1LD_1LC0RA.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_1RB1RB_0LC1RA_1RC1LD_1LC0RA
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 1; SWinL 5; SCycR 2; SWin 1]).
    vm_compute; reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_1RB1RB_0LC1RA_1RC1LD_1LC0RA
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 1; SWinL 4]).
    vm_compute; reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB1RB_0LC1RA_1RC1LD_1LC0RA
      with (l := []).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB1RB_0LC1RA_1RC1LD_1LC0RA
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 1; SWinL 5]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB1RB_0LC1RA_1RC1LD_1LC0RA
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 1; SWinL 1]).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB1RB_0LC1RA_1RC1LD_1LC0RA
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB1RB_0LC1RA_1RC1LD_1LC0RA
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 1]).
    vm_compute; reflexivity.
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_1RB1RB_0LC1RA_1RC1LD_1LC0RA
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 1; SWinL 3]).
    vm_compute; reflexivity.
Qed.

Theorem nqhtr_1RB1RB_0LC1RA_1RC1LD_1LC0RA : NeverQuasiHaltsTr tm_1RB1RB_0LC1RA_1RC1LD_1LC0RA.
Proof.
  apply (glue_neverqhtr tm_1RB1RB_0LC1RA_1RC1LD_1LC0RA pins_1RB1RB_0LC1RA_1RC1LD_1LC0RA Cc 1).
  - exact boot_1RB1RB_0LC1RA_1RC1LD_1LC0RA.
  - intros p _. apply lap_1RB1RB_0LC1RA_1RC1LD_1LC0RA.
  - intros t Ht p _. apply fire_1RB1RB_0LC1RA_1RC1LD_1LC0RA. exact Ht.
Qed.

Theorem nonhalt_1RB1RB_0LC1RA_1RC1LD_1LC0RA : NonHalt tm_1RB1RB_0LC1RA_1RC1LD_1LC0RA.
Proof. apply never_qh_tr_nonhalt, nqhtr_1RB1RB_0LC1RA_1RC1LD_1LC0RA. Qed.

End LAPT_1RB1RB_0LC1RA_1RC1LD_1LC0RA.

Module LAPT_1RB1RB_0LC1RB_1LA1LD_1LC0RA.
(** * LAPT_1RB1RB_0LC1RB_1LA1LD_1LC0RA: TRANSITION-LEVEL board for machine 1RB1RB_0LC1RB_1LA1LD_1LC0RA, boarded by CERTIFICATE.

    Auto-emitted by tools/counters/emit_lapcert.py (UNTRUSTED emitter; the Coq
    kernel re-runs the checker on every line below).  Left-growth binary
    counter under the Jp digit alphabet (JpCounter.v), anchored at

      Cc p = (StB, (Jp p ++ [S0], S0, []))

    The lap is DATA, not a proof script: each branch is a list of steps for
    [Checkers/LapDecider.v], run by the kernel through [vm_compute] and
    discharged by the single theorem [srun_sound].

      interior  (cview p = (j, Some q0)):  j=0: 4 ; j=S j': 4*j'+8 steps
      overflow  (cview p = (S j, None)):   boot 4*j+14, then the inner counter's own laps to the
                                           all-ones fill, then exit 4*j+6

    The interior branch closes EXACTLY (which is what feeds
    [LapCertGlue.reach_ovf]); the overflow branch closes one blank short of
    the anchor tail, hence up to [lift].

    Differentially validated against the raw simulator on BOTH branches --
    step counts AND exact configurations -- for 192 interior anchors (interior); 6 overflow phases, j = 2..7 (246 inner laps) (nested overflow).
    Axiom footprint: [functional_extensionality_dep] (via [CTape.lift]). *)
Import Arith Lia Bool List PArith Wellfounded.
Import BBB4_Statement CTape.
Import WTape LapGlue LapGlueQH LapGlueAbs
                                  MonoCounter JpCounter JpCounter LapCertGlue LapCertGlueLift IXPGadgets NestedLap NestedLapLift.
Import TNF_QH.
