Definition mk_1RB1RB_0LC1RB_1LA1LD_1LC0RA (w : Sym) (d : Dir) (n : St) : option Trans := Some (mkTrans w d n).
Local Notation mk := mk_1RB1RB_0LC1RB_1LA1LD_1LC0RA.

(** 1RB1RB_0LC1RB_1LA1LD_1LC0RA *)
Definition tm_1RB1RB_0LC1RB_1LA1LD_1LC0RA : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB | StA, S1 => mk S1 DR StB
  | StB, S0 => mk S0 DL StC | StB, S1 => mk S1 DR StB
  | StC, S0 => mk S1 DL StA | StC, S1 => mk S1 DL StD
  | StD, S0 => mk S1 DL StC | StD, S1 => mk S0 DR StA end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_1RB1RB_0LC1RB_1LA1LD_1LC0RA : list Instr := [].
Definition tmw_1RB1RB_0LC1RB_1LA1LD_1LC0RA : TM := tm_wrap_trs tm_1RB1RB_0LC1RB_1LA1LD_1LC0RA pins_1RB1RB_0LC1RB_1LA1LD_1LC0RA.
