Definition Cc_1RB1RB_0LC1RB_1LA1LD_1LC0RA (p : positive) : cconf := (StB, (Jp p ++ [S0], S0, [])).
Local Notation Cc := Cc_1RB1RB_0LC1RB_1LA1LD_1LC0RA.

(** ** The certificate *)

(** j = 0: the repeated block is absent, so the whole lap is concrete. *)
Definition Z0_1RB1RB_0LC1RB_1LA1LD_1LC0RA : sconf := mkC StB (mkS [S1;S1] [] 0 0 []) S0 (mkS [] [] 0 0 []).
Definition Z1_1RB1RB_0LC1RB_1LA1LD_1LC0RA : sconf := mkC StB (mkS [S1;S0] [] 0 0 []) S0 (mkS [] [] 0 0 []).
Definition chz_1RB1RB_0LC1RB_1LA1LD_1LC0RA : list lstep := [SWin 4].

Lemma run_z_1RB1RB_0LC1RB_1LA1LD_1LC0RA : srun tm false true chz_1RB1RB_0LC1RB_1LA1LD_1LC0RA Z0_1RB1RB_0LC1RB_1LA1LD_1LC0RA = Some (Z1_1RB1RB_0LC1RB_1LA1LD_1LC0RA, 0, 4).
