Definition P0_1RB1RB_0LC1RB_1LA1LD_1LC0RA : sconf := mkC StB (mkS [S1;S0] [S1;S0] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 []).
Definition P1_1RB1RB_0LC1RB_1LA1LD_1LC0RA : sconf := mkC StB (mkS [S1;S1] [S1;S1] 1 0 [S1;S0]) S0 (mkS [] [] 0 0 []).
Definition chp_1RB1RB_0LC1RB_1LA1LD_1LC0RA : list lstep := [SWin 2; SCycL 2 0; SWin 4; SCycR 2; SWin 2].

Lemma run_p_1RB1RB_0LC1RB_1LA1LD_1LC0RA : srun tm false true chp_1RB1RB_0LC1RB_1LA1LD_1LC0RA P0_1RB1RB_0LC1RB_1LA1LD_1LC0RA = Some (P1_1RB1RB_0LC1RB_1LA1LD_1LC0RA, 4, 8).
Proof. vm_compute. reflexivity. Qed.

Definition B0_1RB1RB_0LC1RB_1LA1LD_1LC0RA : sconf := mkC StB (mkS [] [S1;S0] 1 0 [S1;S0]) S0 (mkS [] [] 0 0 []).
Definition B1_1RB1RB_0LC1RB_1LA1LD_1LC0RA : sconf := mkC StB (mkS [] [S1;S1] 1 1 [S1;S0]) S0 (mkS [] [] 0 0 []).
(** ** The INNER anchor family -- Jp at StD *)
Definition Cin_1RB1RB_0LC1RB_1LA1LD_1LC0RA (v : positive) : cconf := (StD, (Jp v ++ [S1], S0, [S1])).
Local Notation Cin := Cin_1RB1RB_0LC1RB_1LA1LD_1LC0RA.

(** [E (2^n) = A^n C]: the value this family's count starts at. *)
Lemma epow2_1RB1RB_0LC1RB_1LA1LD_1LC0RA : forall n, Jp (pow2 n) = rep [S1;S1] n ++ [S1].
Proof. induction n; simpl; [reflexivity | rewrite IHn; reflexivity]. Qed.

(** Its own INTERIOR lap -- ordinary and affine.  Iterating it to the fill is
    where a [Theta(2^j)] lives, and [inner_to_fill_lift] keeps it inside an
    existential. *)
Definition AI0_1RB1RB_0LC1RB_1LA1LD_1LC0RA : sconf := mkC StD (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [S1] [] 0 0 []).
Definition AI1_1RB1RB_0LC1RB_1LA1LD_1LC0RA : sconf := mkC StD (mkS [] [S1;S1] 1 0 [S1;S0]) S0 (mkS [S1;S0] [] 0 0 []).
Definition chn_1RB1RB_0LC1RB_1LA1LD_1LC0RA : list lstep := [SCycL 2 0; SWin 4; SCycR 2; SWin 1; SWinR 7].

Lemma run_inner_1RB1RB_0LC1RB_1LA1LD_1LC0RA : srun tm false true chn_1RB1RB_0LC1RB_1LA1LD_1LC0RA AI0_1RB1RB_0LC1RB_1LA1LD_1LC0RA = Some (AI1_1RB1RB_0LC1RB_1LA1LD_1LC0RA, 4, 12).
Proof. vm_compute. reflexivity. Qed.

(** *** boot: the outer overflow anchor -> the first inner anchor at [pow2 j] *)
Definition BB1_1RB1RB_0LC1RB_1LA1LD_1LC0RA : sconf := mkC StD (mkS [] [S1;S1] 1 0 [S1;S1]) S0 (mkS [S1;S0] [] 0 0 []).
Definition chb_1RB1RB_0LC1RB_1LA1LD_1LC0RA : list lstep := [SRotL 1; SWin 1; SCycL 2 0; SWin 1; SWinL 5; SCycR 2; SWin 2; SRotL 1; SWin 5].

Lemma run_boot_1RB1RB_0LC1RB_1LA1LD_1LC0RA : srun tm true true chb_1RB1RB_0LC1RB_1LA1LD_1LC0RA B0_1RB1RB_0LC1RB_1LA1LD_1LC0RA = Some (BB1_1RB1RB_0LC1RB_1LA1LD_1LC0RA, 4, 14).
Proof. vm_compute. reflexivity. Qed.

(** *** exit: the last inner all-ones fill -> the outer successor *)
Definition BE0_1RB1RB_0LC1RB_1LA1LD_1LC0RA : sconf := mkC StD (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [S1] [] 0 0 []).
Definition che_1RB1RB_0LC1RB_1LA1LD_1LC0RA : list lstep := [SCycL 2 0; SWin 4; SCycR 2; SWin 1; SWinR 1; SFoldL 1].

Lemma run_exit_1RB1RB_0LC1RB_1LA1LD_1LC0RA : srun tm true true che_1RB1RB_0LC1RB_1LA1LD_1LC0RA BE0_1RB1RB_0LC1RB_1LA1LD_1LC0RA = Some (B1_1RB1RB_0LC1RB_1LA1LD_1LC0RA, 4, 6).
Proof. vm_compute. reflexivity. Qed.

(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_1RB1RB_0LC1RB_1LA1LD_1LC0RA : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Jp q0 ++ [S0]) [] 0 Z0_1RB1RB_0LC1RB_1LA1LD_1LC0RA /\
  cden (Jp q0 ++ [S0]) [] 0 Z1_1RB1RB_0LC1RB_1LA1LD_1LC0RA = Cc (Pos.succ p).
Proof.
  intros p q0 E. destruct (JpCounter.cview_some_J p 0 q0 E) as (H1 & H2).
  unfold Cc_1RB1RB_0LC1RB_1LA1LD_1LC0RA, cden, Z0_1RB1RB_0LC1RB_1LA1LD_1LC0RA, Z1_1RB1RB_0LC1RB_1LA1LD_1LC0RA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gp_1RB1RB_0LC1RB_1LA1LD_1LC0RA : forall p j q0, cview p = (S j, Some q0) ->
  Cc p = cden (Jp q0 ++ [S0]) [] j P0_1RB1RB_0LC1RB_1LA1LD_1LC0RA /\
  cden (Jp q0 ++ [S0]) [] j P1_1RB1RB_0LC1RB_1LA1LD_1LC0RA = Cc (Pos.succ p).
Proof.
  intros p j q0 E. destruct (JpCounter.cview_some_J p (S j) q0 E) as (H1 & H2).
  unfold Cc_1RB1RB_0LC1RB_1LA1LD_1LC0RA, cden, P0_1RB1RB_0LC1RB_1LA1LD_1LC0RA, P1_1RB1RB_0LC1RB_1LA1LD_1LC0RA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_1RB1RB_0LC1RB_1LA1LD_1LC0RA : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct j as [|j'].
  - destruct (gz_1RB1RB_0LC1RB_1LA1LD_1LC0RA p q0 E) as (HA & HB).
    exists (0 * 0 + 4). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chz_1RB1RB_0LC1RB_1LA1LD_1LC0RA Z0_1RB1RB_0LC1RB_1LA1LD_1LC0RA Z1_1RB1RB_0LC1RB_1LA1LD_1LC0RA 0 4
               run_z_1RB1RB_0LC1RB_1LA1LD_1LC0RA (Jp q0 ++ [S0]) [] 0
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
  - destruct (gp_1RB1RB_0LC1RB_1LA1LD_1LC0RA p j' q0 E) as (HA & HB).
    exists (4 * j' + 8). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_1RB1RB_0LC1RB_1LA1LD_1LC0RA P0_1RB1RB_0LC1RB_1LA1LD_1LC0RA P1_1RB1RB_0LC1RB_1LA1LD_1LC0RA 4 8
               run_p_1RB1RB_0LC1RB_1LA1LD_1LC0RA (Jp q0 ++ [S0]) [] j'
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
Qed.

Lemma gso_1RB1RB_0LC1RB_1LA1LD_1LC0RA : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB1RB_0LC1RB_1LA1LD_1LC0RA.
Proof.
  intros p j E. destruct (JpCounter.cview_none_J p j E) as (H1 & _).
  unfold Cc_1RB1RB_0LC1RB_1LA1LD_1LC0RA, cden, B0_1RB1RB_0LC1RB_1LA1LD_1LC0RA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_1RB1RB_0LC1RB_1LA1LD_1LC0RA : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB1RB_0LC1RB_1LA1LD_1LC0RA : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1RB_0LC1RB_1LA1LD_1LC0RA) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (JpCounter.cview_none_J p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB1RB_0LC1RB_1LA1LD_1LC0RA
             = (StB, (rep [S1;S1] (S j) ++ [S1;S0], S0, []))).
  { unfold cden, B1_1RB1RB_0LC1RB_1LA1LD_1LC0RA, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StB, (rep [S1;S1] (S j) ++ [S1;S0], S0, []))).
  { unfold Cc_1RB1RB_0LC1RB_1LA1LD_1LC0RA. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. reflexivity.
Qed.

Lemma gsn_1RB1RB_0LC1RB_1LA1LD_1LC0RA : forall v i q0, cview v = (i, Some q0) ->
  Cin v = cden (Jp q0 ++ [S1]) [] i AI0_1RB1RB_0LC1RB_1LA1LD_1LC0RA.
Proof.
  intros v i q0 E. destruct (JpCounter.cview_some_J v i q0 E) as (H1 & _).
  unfold Cin_1RB1RB_0LC1RB_1LA1LD_1LC0RA, cden, AI0_1RB1RB_0LC1RB_1LA1LD_1LC0RA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S0] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gen_1RB1RB_0LC1RB_1LA1LD_1LC0RA : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Jp q0 ++ [S1]) [] i AI1_1RB1RB_0LC1RB_1LA1LD_1LC0RA) = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E. destruct (JpCounter.cview_some_J v i q0 E) as (_ & H2).
  unfold Cin_1RB1RB_0LC1RB_1LA1LD_1LC0RA, cden, AI1_1RB1RB_0LC1RB_1LA1LD_1LC0RA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  replace (0 * i + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  change ([S1;S0]) with (([S1]) ++ [S0]).
  rewrite !lift_app_blank.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S1] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapin_1RB1RB_0LC1RB_1LA1LD_1LC0RA : forall v i q0, cview v = (i, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cin v) = Some c'
               /\ lift c' = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E.
  exists (4 * i + 12), (cden (Jp q0 ++ [S1]) [] i AI1_1RB1RB_0LC1RB_1LA1LD_1LC0RA).
  split; [lia|]. split; [| exact (gen_1RB1RB_0LC1RB_1LA1LD_1LC0RA v i q0 E)].
  rewrite (gsn_1RB1RB_0LC1RB_1LA1LD_1LC0RA v i q0 E).
  exact (srun_sound tm false true chn_1RB1RB_0LC1RB_1LA1LD_1LC0RA AI0_1RB1RB_0LC1RB_1LA1LD_1LC0RA AI1_1RB1RB_0LC1RB_1LA1LD_1LC0RA 4 12
           run_inner_1RB1RB_0LC1RB_1LA1LD_1LC0RA (Jp q0 ++ [S1]) [] i
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

(** The chain into this family lands on its anchor up to 0/1
    trailing blanks. *)
Lemma gbo_1RB1RB_0LC1RB_1LA1LD_1LC0RA : forall j, lift (cden [] [] j BB1_1RB1RB_0LC1RB_1LA1LD_1LC0RA) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_1RB1RB_0LC1RB_1LA1LD_1LC0RA = (StD, (rep [S1;S1] j ++ [S1;S1], S0, ([S1]) ++ [S0]))).
  { unfold cden, BB1_1RB1RB_0LC1RB_1LA1LD_1LC0RA, sden;
