    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB1RB_0LC1RD_1RA1LC_0LA0RA
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 4]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB1RB_0LC1RD_1RA1LC_0LA0RA
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 2]).
    vm_compute; reflexivity.
