(** ** The certificate *)

Definition A0_1RB1RB_0LC1RD_1RA1LC_0RA0LB : sconf := mkC StB (mkS [] [S1;S1;S1] 1 0 [S1;S0;S1]) S0 (mkS [] [] 0 0 []).
Definition A1_1RB1RB_0LC1RD_1RA1LC_0RA0LB : sconf := mkC StB (mkS [] [S1;S0;S1] 1 0 [S1;S1;S1]) S0 (mkS [] [] 0 0 []).
