Definition B0_1RB1RB_0LC1RD_1RA1LC_0RA0LB : sconf := mkC StB (mkS [] [S1;S1;S1] 1 0 [S1;S0;S1;S1;S1;S0]) S0 (mkS [] [] 0 0 []).
Definition B1_1RB1RB_0LC1RD_1RA1LC_0RA0LB : sconf := mkC StB (mkS [] [S1;S0;S1] 1 1 [S1;S0;S1;S1;S1]) S0 (mkS [] [] 0 0 []).
(** ** The INNER anchor family -- Ap_Alph_101_111_11 at StB *)
Definition Cin_1RB1RB_0LC1RD_1RA1LC_0RA0LB (v : positive) : cconf := (StB, (Ap_Alph_101_111_11 v ++ [S1;S1;S1], S0, [])).
