      with (l := []).
    vm_compute; reflexivity.
  - (* B1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1RB_0LC1RD_1RA1LC_0RA0LB (StB, S1)).
    intros p1 j1 E1.
    exact (firex_1RB1RB_0LC1RD_1RA1LC_0RA0LB [SRotL 1; SWin 1; SCycL 3 0; SWin 4; SWinL 3] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB1RB_0LC1RD_1RA1LC_0RA0LB
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 1]).
