Lemma geo_1RB1RB_0RC1RA_1LC0LD_0RA0LC : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1RB_0RC1RA_1LC0LD_0RA0LC) = lift (Cc (Pos.succ p)).
