Lemma gz_1RB1RB_0RC1RA_1LC0LD_0RA0LD : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Dp q0 ++ [S0]) [] 0 Z0_1RB1RB_0RC1RA_1LC0LD_0RA0LD /\
