(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_1RB1RB_1LA0RC_0LD1RA_1RC1LD : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Ap_Alph_011_111_1 q0 ++ [S0]) [] 0 Z0_1RB1RB_1LA0RC_0LD1RA_1RC1LD /\
  cden (Ap_Alph_011_111_1 q0 ++ [S0]) [] 0 Z1_1RB1RB_1LA0RC_0LD1RA_1RC1LD = Cc (Pos.succ p).
Proof.
  intros p q0 E. destruct (Alph_011_111_1.cview_some_Alph_011_111_1 p 0 q0 E) as (H1 & H2).
  unfold Cc_1RB1RB_1LA0RC_0LD1RA_1RC1LD, cden, Z0_1RB1RB_1LA0RC_0LD1RA_1RC1LD, Z1_1RB1RB_1LA0RC_0LD1RA_1RC1LD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gp_1RB1RB_1LA0RC_0LD1RA_1RC1LD : forall p j q0, cview p = (S j, Some q0) ->
  Cc p = cden (Ap_Alph_011_111_1 q0 ++ [S0]) [] j P0_1RB1RB_1LA0RC_0LD1RA_1RC1LD /\
  cden (Ap_Alph_011_111_1 q0 ++ [S0]) [] j P1_1RB1RB_1LA0RC_0LD1RA_1RC1LD = Cc (Pos.succ p).
Proof.
  intros p j q0 E. destruct (Alph_011_111_1.cview_some_Alph_011_111_1 p (S j) q0 E) as (H1 & H2).
  unfold Cc_1RB1RB_1LA0RC_0LD1RA_1RC1LD, cden, P0_1RB1RB_1LA0RC_0LD1RA_1RC1LD, P1_1RB1RB_1LA0RC_0LD1RA_1RC1LD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_1RB1RB_1LA0RC_0LD1RA_1RC1LD : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct j as [|j'].
  - destruct (gz_1RB1RB_1LA0RC_0LD1RA_1RC1LD p q0 E) as (HA & HB).
    exists (0 * 0 + 2). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chz_1RB1RB_1LA0RC_0LD1RA_1RC1LD Z0_1RB1RB_1LA0RC_0LD1RA_1RC1LD Z1_1RB1RB_1LA0RC_0LD1RA_1RC1LD 0 2
               run_z_1RB1RB_1LA0RC_0LD1RA_1RC1LD (Ap_Alph_011_111_1 q0 ++ [S0]) [] 0
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
  - destruct (gp_1RB1RB_1LA0RC_0LD1RA_1RC1LD p j' q0 E) as (HA & HB).
    exists (6 * j' + 8). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_1RB1RB_1LA0RC_0LD1RA_1RC1LD P0_1RB1RB_1LA0RC_0LD1RA_1RC1LD P1_1RB1RB_1LA0RC_0LD1RA_1RC1LD 6 8
               run_p_1RB1RB_1LA0RC_0LD1RA_1RC1LD (Ap_Alph_011_111_1 q0 ++ [S0]) [] j'
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
