Lemma gso_1RB1RB_1LA0RC_0LD1RA_1RC1LD : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB1RB_1LA0RC_0LD1RA_1RC1LD.
Proof.
  intros p j E. destruct (Alph_011_111_1.cview_none_Alph_011_111_1 p j E) as (H1 & _).
  unfold Cc_1RB1RB_1LA0RC_0LD1RA_1RC1LD, cden, B0_1RB1RB_1LA0RC_0LD1RA_1RC1LD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_1RB1RB_1LA0RC_0LD1RA_1RC1LD : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB1RB_1LA0RC_0LD1RA_1RC1LD : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1RB_1LA0RC_0LD1RA_1RC1LD) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (Alph_011_111_1.cview_none_Alph_011_111_1 p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB1RB_1LA0RC_0LD1RA_1RC1LD
             = (StC, (rep [S0;S1;S1] (S j) ++ [S1], S0, []))).
  { unfold cden, B1_1RB1RB_1LA0RC_0LD1RA_1RC1LD, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StC, ((rep [S0;S1;S1] (S j) ++ [S1]) ++ [S0], S0, []))).
  { unfold Cc_1RB1RB_1LA0RC_0LD1RA_1RC1LD. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lbl_1RB1RB_1LA0RC_0LD1RA_1RC1LD. reflexivity.
Qed.

(** ** The lap *)

Lemma lap_1RB1RB_1LA0RC_0LD1RA_1RC1LD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB1RB_1LA0RC_0LD1RA_1RC1LD p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1RB_1LA0RC_0LD1RA_1RC1LD B0_1RB1RB_1LA0RC_0LD1RA_1RC1LD B1_1RB1RB_1LA0RC_0LD1RA_1RC1LD 6 8 p j' [] []).
    + exact run_ovf_1RB1RB_1LA0RC_0LD1RA_1RC1LD.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1RB_1LA0RC_0LD1RA_1RC1LD p j' E).
    + exact (geo_1RB1RB_1LA0RC_0LD1RA_1RC1LD p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma boot_1RB1RB_1LA0RC_0LD1RA_1RC1LD : exists t0, stepn tm t0 InitES = Some (lift (Cc 2)).
Proof.
  exists 15.
  assert (H : match csteps tm 15 c0 with
              | Some c => ceqb c (Cc 2) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 15 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB1RB_1LA0RC_0LD1RA_1RC1LD : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1RB_1LA0RC_0LD1RA_1RC1LD = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB1RB_1LA0RC_0LD1RA_1RC1LD p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1RB_1LA0RC_0LD1RA_1RC1LD p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB1RB_1LA0RC_0LD1RA_1RC1LD : forall t, ~ In t pins_1RB1RB_1LA0RC_0LD1RA_1RC1LD ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB1RB_1LA0RC_0LD1RA_1RC1LD.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_1RB1RB_1LA0RC_0LD1RA_1RC1LD
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 2; SCycR 3; SWin 1]).
    vm_compute; reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_1RB1RB_1LA0RC_0LD1RA_1RC1LD
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 2; SCycR 3; SWin 1; SWinR 2]).
    vm_compute; reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB1RB_1LA0RC_0LD1RA_1RC1LD
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 2; SCycR 3; SWin 1; SWinR 1]).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB1RB_1LA0RC_0LD1RA_1RC1LD
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 2; SCycR 3; SWin 1; SWinR 3]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB1RB_1LA0RC_0LD1RA_1RC1LD
      with (l := []).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB1RB_1LA0RC_0LD1RA_1RC1LD
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 2]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB1RB_1LA0RC_0LD1RA_1RC1LD
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 1]).
    vm_compute; reflexivity.
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_1RB1RB_1LA0RC_0LD1RA_1RC1LD
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
Qed.

Theorem nqhtr_1RB1RB_1LA0RC_0LD1RA_1RC1LD : NeverQuasiHaltsTr tm_1RB1RB_1LA0RC_0LD1RA_1RC1LD.
Proof.
  apply (glue_neverqhtr tm_1RB1RB_1LA0RC_0LD1RA_1RC1LD pins_1RB1RB_1LA0RC_0LD1RA_1RC1LD Cc 2).
  - exact boot_1RB1RB_1LA0RC_0LD1RA_1RC1LD.
  - intros p _. apply lap_1RB1RB_1LA0RC_0LD1RA_1RC1LD.
  - intros t Ht p _. apply fire_1RB1RB_1LA0RC_0LD1RA_1RC1LD. exact Ht.
Qed.

Theorem nonhalt_1RB1RB_1LA0RC_0LD1RA_1RC1LD : NonHalt tm_1RB1RB_1LA0RC_0LD1RA_1RC1LD.
Proof. apply never_qh_tr_nonhalt, nqhtr_1RB1RB_1LA0RC_0LD1RA_1RC1LD. Qed.

