(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_1RB1RB_1LC0RB_1RA0LD_0RA0LC : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Ap_Alph_00_10_1 q0 ++ [S0]) [] 0 Z0_1RB1RB_1LC0RB_1RA0LD_0RA0LC /\
  lift (cden (Ap_Alph_00_10_1 q0 ++ [S0]) [] 0 Z1_1RB1RB_1LC0RB_1RA0LD_0RA0LC) = lift (Cc (Pos.succ p)).
Proof.
  intros p q0 E. destruct (Alph_00_10_1.cview_some_Alph_00_10_1 p 0 q0 E) as (H1 & H2).
  unfold Cc_1RB1RB_1LC0RB_1RA0LD_0RA0LC, cden, Z0_1RB1RB_1LC0RB_1RA0LD_0RA0LC, Z1_1RB1RB_1LC0RB_1RA0LD_0RA0LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - cbn [rep app Nat.mul Nat.add]; rewrite ?app_nil_r.
    change ([S0]) with (([]) ++ [S0]).
    rewrite !lift_app_blank.
    rewrite H2; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gp_1RB1RB_1LC0RB_1RA0LD_0RA0LC : forall p j q0, cview p = (S j, Some q0) ->
  Cc p = cden (Ap_Alph_00_10_1 q0 ++ [S0]) [] j P0_1RB1RB_1LC0RB_1RA0LD_0RA0LC /\
  lift (cden (Ap_Alph_00_10_1 q0 ++ [S0]) [] j P1_1RB1RB_1LC0RB_1RA0LD_0RA0LC) = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct (Alph_00_10_1.cview_some_Alph_00_10_1 p (S j) q0 E) as (H1 & H2).
  unfold Cc_1RB1RB_1LC0RB_1RA0LD_0RA0LC, cden, P0_1RB1RB_1LC0RB_1RA0LD_0RA0LC, P1_1RB1RB_1LC0RB_1RA0LD_0RA0LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - cbn [rep app Nat.mul Nat.add]; rewrite ?app_nil_r.
    change ([S0]) with (([]) ++ [S0]).
    rewrite !lift_app_blank.
    rewrite H2; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_1RB1RB_1LC0RB_1RA0LD_0RA0LC : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct j as [|j'].
  - destruct (gz_1RB1RB_1LC0RB_1RA0LD_0RA0LC p q0 E) as (HA & HB).
    exists (0 * 0 + 4), (cden (Ap_Alph_00_10_1 q0 ++ [S0]) [] 0 Z1_1RB1RB_1LC0RB_1RA0LD_0RA0LC).
    split; [lia|]. split; [| exact HB].
    rewrite HA.
    exact (srun_sound tm false true chz_1RB1RB_1LC0RB_1RA0LD_0RA0LC Z0_1RB1RB_1LC0RB_1RA0LD_0RA0LC Z1_1RB1RB_1LC0RB_1RA0LD_0RA0LC 0 4
             run_z_1RB1RB_1LC0RB_1RA0LD_0RA0LC (Ap_Alph_00_10_1 q0 ++ [S0]) [] 0
             ltac:(discriminate) ltac:(reflexivity)).
  - destruct (gp_1RB1RB_1LC0RB_1RA0LD_0RA0LC p j' q0 E) as (HA & HB).
    exists (6 * j' + 10), (cden (Ap_Alph_00_10_1 q0 ++ [S0]) [] j' P1_1RB1RB_1LC0RB_1RA0LD_0RA0LC).
    split; [lia|]. split; [| exact HB].
    rewrite HA.
    exact (srun_sound tm false true chp_1RB1RB_1LC0RB_1RA0LD_0RA0LC P0_1RB1RB_1LC0RB_1RA0LD_0RA0LC P1_1RB1RB_1LC0RB_1RA0LD_0RA0LC 6 10
             run_p_1RB1RB_1LC0RB_1RA0LD_0RA0LC (Ap_Alph_00_10_1 q0 ++ [S0]) [] j'
             ltac:(discriminate) ltac:(reflexivity)).
Qed.

Lemma gso_1RB1RB_1LC0RB_1RA0LD_0RA0LC : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB1RB_1LC0RB_1RA0LD_0RA0LC.
