Lemma lbl_1RB1RB_1LC1RA_0RD0LC_1LB0RA : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB1RB_1LC1RA_0RD0LC_1LB0RA : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1RB_1LC1RA_0RD0LC_1LB0RA) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (BpCounter.cview_none_B p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB1RB_1LC1RA_0RD0LC_1LB0RA
             = (StC, (rep [S0;S0] (S j) ++ [S0;S1], S0, ([]) ++ [S0]))).
  { unfold cden, B1_1RB1RB_1LC1RA_0RD0LC_1LB0RA, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StC, ((rep [S0;S0] (S j) ++ [S0;S1]) ++ [S0], S0, []))).
  { unfold Cc_1RB1RB_1LC1RA_0RD0LC_1LB0RA. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lift_app_blank. rewrite !lbl_1RB1RB_1LC1RA_0RD0LC_1LB0RA. reflexivity.
Qed.

(** ** The lap *)

Lemma lap_1RB1RB_1LC1RA_0RD0LC_1LB0RA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB1RB_1LC1RA_0RD0LC_1LB0RA p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1RB_1LC1RA_0RD0LC_1LB0RA B0_1RB1RB_1LC1RA_0RD0LC_1LB0RA B1_1RB1RB_1LC1RA_0RD0LC_1LB0RA 4 12 p j' [] []).
    + exact run_ovf_1RB1RB_1LC1RA_0RD0LC_1LB0RA.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1RB_1LC1RA_0RD0LC_1LB0RA p j' E).
    + exact (geo_1RB1RB_1LC1RA_0RD0LC_1LB0RA p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma boot_1RB1RB_1LC1RA_0RD0LC_1LB0RA : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 3.
  assert (H : match csteps tm 3 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 3 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB1RB_1LC1RA_0RD0LC_1LB0RA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1RB_1LC1RA_0RD0LC_1LB0RA = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB1RB_1LC1RA_0RD0LC_1LB0RA p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1RB_1LC1RA_0RD0LC_1LB0RA p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB1RB_1LC1RA_0RD0LC_1LB0RA : forall t, ~ In t pins_1RB1RB_1LC1RA_0RD0LC_1LB0RA ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n c', 0 < n /\ csteps tm n (Cc p0) = Some c'
                         /\ lift c' = lift (Cc (Pos.succ p0)))
    by exact lapi_1RB1RB_1LC1RA_0RD0LC_1LB0RA.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1RB_1LC1RA_0RD0LC_1LB0RA [SWin 2; SWinR 4; SCycL 2 0; SWin 1] (StA, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* A1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1RB_1LC1RA_0RD0LC_1LB0RA [SWin 2; SWinR 3] (StA, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B0 *)
