Lemma fireo_1RB1RB_1LC1RB_0LD1LD_0RA0LC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1RB_1LC1RB_0LD1LD_0RA0LC = Some t ->
