                         /\ lift c' = lift (Cc (Pos.succ p0)))
    by exact lapi_1RB1RB_1LC1RB_0LD1LD_0RA0LC.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1RB_1LC1RB_0LD1LD_0RA0LC [SWin 1; SWinR 3; SCycL 2 0; SWin 6; SCycR 2; SWin 2; SWinR 2] (StA, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* A1 *)
