Lemma gz_1RB1RB_1LC1RB_0RA1LD_0RA0LC : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] 0 Z0_1RB1RB_1LC1RB_0RA1LD_0RA0LC /\
  cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] 0 Z1_1RB1RB_1LC1RB_0RA1LD_0RA0LC = Cc (Pos.succ p).
