(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB1RB_1LC1RB_0RA1LD_1LC0LC : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j A0_1RB1RB_1LC1RB_0RA1LD_1LC0LC.
