  split; [lia|]. split; [| exact (gei_1RB1RB_1LC1RB_0RA1LD_1RA0LC p j q0 E)].
  rewrite (gsi_1RB1RB_1LC1RB_0RA1LD_1RA0LC p j q0 E).
  exact (srun_sound tm false true chi_1RB1RB_1LC1RB_0RA1LD_1RA0LC A0_1RB1RB_1LC1RB_0RA1LD_1RA0LC A1_1RB1RB_1LC1RB_0RA1LD_1RA0LC 4 16
           run_int_1RB1RB_1LC1RB_0RA1LD_1RA0LC (Ap_Alph_10_11_11 q0 ++ [S0]) [] j
           ltac:(discriminate) ltac:(reflexivity)).
