Definition AIZ1_1RB1RB_1LC1RB_1RA1LD_0RA0LC : sconf := mkC StD (mkS [S1;S1] [] 0 0 []) S0 (mkS [] [] 0 0 []).
Definition chnz_1RB1RB_1LC1RB_1RA1LD_0RA0LC : list lstep := [SWin 4].

Lemma run_innerz_1RB1RB_1LC1RB_1RA1LD_0RA0LC : srun tm false true chnz_1RB1RB_1LC1RB_1RA1LD_0RA0LC AIZ0_1RB1RB_1LC1RB_1RA1LD_0RA0LC = Some (AIZ1_1RB1RB_1LC1RB_1RA1LD_0RA0LC, 0, 4).
Proof. vm_compute. reflexivity. Qed.

Definition AIP0_1RB1RB_1LC1RB_1RA1LD_0RA0LC : sconf := mkC StD (mkS [S1;S1] [S1;S1] 1 0 [S1;S0]) S0 (mkS [] [] 0 0 []).
Definition AIP1_1RB1RB_1LC1RB_1RA1LD_0RA0LC : sconf := mkC StD (mkS [S1;S0] [S1;S0] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 []).
Definition chnp_1RB1RB_1LC1RB_1RA1LD_0RA0LC : list lstep := [SWin 2; SCycL 2 0; SWin 4; SCycR 2; SWin 2].

Lemma run_innerp_1RB1RB_1LC1RB_1RA1LD_0RA0LC : srun tm false true chnp_1RB1RB_1LC1RB_1RA1LD_0RA0LC AIP0_1RB1RB_1LC1RB_1RA1LD_0RA0LC = Some (AIP1_1RB1RB_1LC1RB_1RA1LD_0RA0LC, 4, 8).
Proof. vm_compute. reflexivity. Qed.

(** The OFFSET start: [E (2^(n+2)+2)] is fixed digit blocks, then the rep.
    Its block count is one short of the outer index, which is why [lapo_]
    below REINDEXES at [j = S j']. *)
Lemma epre_1RB1RB_1LC1RB_1RA1LD_0RA0LC : forall n, Ip (xO (xI (pow2 n))) = [S1;S0;S1;S1] ++ rep [S1;S0] n ++ [S1].
Proof.
  intro n. cbn [Ip]. rewrite epow2_1RB1RB_1LC1RB_1RA1LD_0RA0LC.
  cbn [app]. rewrite <- ?app_assoc. cbn [app]. reflexivity.
Qed.

(** Rotating one fixed cell across a rep -- the bridge between a chain's
    natural landing frame and the encoding's block frame ([WTape.rep_rot],
    with the trailing cell fused into the tail). *)
Lemma rrc_1RB1RB_1LC1RB_1RA1LD_0RA0LC : forall (x : Sym) (u : list Sym) k (Y : list Sym),
  rep (x :: u) k ++ x :: Y = x :: rep (u ++ [x]) k ++ Y.
Proof.
  intros. change (x :: Y) with ([x] ++ Y). rewrite app_assoc, <- rep_rot.
  cbn [app]. rewrite <- ?app_assoc. reflexivity.
Qed.

(** *** boot: the outer overflow anchor -> the first inner anchor at [pow2 j] *)
Definition BB1_1RB1RB_1LC1RB_1RA1LD_0RA0LC : sconf := mkC StD (mkS [S1;S0;S1;S1] [S1;S0] 1 1 [S1;S1]) S0 (mkS [] [] 0 0 []).
Definition chb_1RB1RB_1LC1RB_1RA1LD_0RA0LC : list lstep := [SRotL 1; SWin 1; SRotL 1; SWin 1; SCycL 2 0; SWin 6; SCycR 2; SWin 4; SRotL 1; SWin 4; SWinR 1].

Lemma run_boot_1RB1RB_1LC1RB_1RA1LD_0RA0LC : srun tm true true chb_1RB1RB_1LC1RB_1RA1LD_0RA0LC B0_1RB1RB_1LC1RB_1RA1LD_0RA0LC = Some (BB1_1RB1RB_1LC1RB_1RA1LD_0RA0LC, 4, 21).
Proof. vm_compute. reflexivity. Qed.

(** *** exit: the last inner all-ones fill -> the outer successor *)
Definition BE0_1RB1RB_1LC1RB_1RA1LD_0RA0LC : sconf := mkC StD (mkS [S1] [S1;S1] 1 1 [S1;S1;S0;S1;S1]) S0 (mkS [] [] 0 0 []).
Definition che_1RB1RB_1LC1RB_1RA1LD_0RA0LC : list lstep := [SWin 1; SRotL 1; SWin 1; SCycL 2 0; SWin 4; SCycR 2; SWin 2; SFoldL 1].

Lemma run_exit_1RB1RB_1LC1RB_1RA1LD_0RA0LC : srun tm true true che_1RB1RB_1LC1RB_1RA1LD_0RA0LC BE0_1RB1RB_1LC1RB_1RA1LD_0RA0LC = Some (B1_1RB1RB_1LC1RB_1RA1LD_0RA0LC, 4, 12).
Proof. vm_compute. reflexivity. Qed.

(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_1RB1RB_1LC1RB_1RA1LD_0RA0LC : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Ap_Alph_10_11_11 q0 ++ [S1;S1;S0]) [] 0 Z0_1RB1RB_1LC1RB_1RA1LD_0RA0LC /\
  cden (Ap_Alph_10_11_11 q0 ++ [S1;S1;S0]) [] 0 Z1_1RB1RB_1LC1RB_1RA1LD_0RA0LC = Cc (Pos.succ p).
Proof.
  intros p q0 E. destruct (Alph_10_11_11.cview_some_Alph_10_11_11 p 0 q0 E) as (H1 & H2).
  unfold Cc_1RB1RB_1LC1RB_1RA1LD_0RA0LC, cden, Z0_1RB1RB_1LC1RB_1RA1LD_0RA0LC, Z1_1RB1RB_1LC1RB_1RA1LD_0RA0LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gp_1RB1RB_1LC1RB_1RA1LD_0RA0LC : forall p j q0, cview p = (S j, Some q0) ->
  Cc p = cden (Ap_Alph_10_11_11 q0 ++ [S1;S1;S0]) [] j P0_1RB1RB_1LC1RB_1RA1LD_0RA0LC /\
  cden (Ap_Alph_10_11_11 q0 ++ [S1;S1;S0]) [] j P1_1RB1RB_1LC1RB_1RA1LD_0RA0LC = Cc (Pos.succ p).
Proof.
  intros p j q0 E. destruct (Alph_10_11_11.cview_some_Alph_10_11_11 p (S j) q0 E) as (H1 & H2).
  unfold Cc_1RB1RB_1LC1RB_1RA1LD_0RA0LC, cden, P0_1RB1RB_1LC1RB_1RA1LD_0RA0LC, P1_1RB1RB_1LC1RB_1RA1LD_0RA0LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_1RB1RB_1LC1RB_1RA1LD_0RA0LC : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct j as [|j'].
  - destruct (gz_1RB1RB_1LC1RB_1RA1LD_0RA0LC p q0 E) as (HA & HB).
    exists (0 * 0 + 4). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chz_1RB1RB_1LC1RB_1RA1LD_0RA0LC Z0_1RB1RB_1LC1RB_1RA1LD_0RA0LC Z1_1RB1RB_1LC1RB_1RA1LD_0RA0LC 0 4
               run_z_1RB1RB_1LC1RB_1RA1LD_0RA0LC (Ap_Alph_10_11_11 q0 ++ [S1;S1;S0]) [] 0
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
  - destruct (gp_1RB1RB_1LC1RB_1RA1LD_0RA0LC p j' q0 E) as (HA & HB).
    exists (4 * j' + 8). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_1RB1RB_1LC1RB_1RA1LD_0RA0LC P0_1RB1RB_1LC1RB_1RA1LD_0RA0LC P1_1RB1RB_1LC1RB_1RA1LD_0RA0LC 4 8
               run_p_1RB1RB_1LC1RB_1RA1LD_0RA0LC (Ap_Alph_10_11_11 q0 ++ [S1;S1;S0]) [] j'
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
Qed.

Lemma gso_1RB1RB_1LC1RB_1RA1LD_0RA0LC : forall p j, cview p = (S (S j), None) ->
  Cc p = cden [] [] j B0_1RB1RB_1LC1RB_1RA1LD_0RA0LC.
Proof.
  intros p j E. destruct (Alph_10_11_11.cview_none_Alph_10_11_11 p (S j) E) as (H1 & _).
  unfold Cc_1RB1RB_1LC1RB_1RA1LD_0RA0LC, cden, B0_1RB1RB_1LC1RB_1RA1LD_0RA0LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 1) with ((S j)) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_1RB1RB_1LC1RB_1RA1LD_0RA0LC : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB1RB_1LC1RB_1RA1LD_0RA0LC : forall p j, cview p = (S (S j), None) ->
  lift (cden [] [] j B1_1RB1RB_1LC1RB_1RA1LD_0RA0LC) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (Alph_10_11_11.cview_none_Alph_10_11_11 p (S j) E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB1RB_1LC1RB_1RA1LD_0RA0LC
             = (StD, (rep [S1;S0] (S (S j)) ++ [S1;S1;S1;S1], S0, []))).
  { unfold cden, B1_1RB1RB_1LC1RB_1RA1LD_0RA0LC, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 2) with (S (S j)) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StD, ((rep [S1;S0] (S (S j)) ++ [S1;S1;S1;S1]) ++ [S0], S0, []))).
  { unfold Cc_1RB1RB_1LC1RB_1RA1LD_0RA0LC. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lbl_1RB1RB_1LC1RB_1RA1LD_0RA0LC. reflexivity.
Qed.

Lemma gsnz_1RB1RB_1LC1RB_1RA1LD_0RA0LC : forall v q0, cview v = (0%nat, Some q0) ->
  Cin v = cden (Ip q0 ++ [S0;S1;S1]) [] 0 AIZ0_1RB1RB_1LC1RB_1RA1LD_0RA0LC.
Proof.
  intros v q0 E. destruct (ILCounter.cview_some_I v 0 q0 E) as (H1 & _).
  unfold Cin_1RB1RB_1LC1RB_1RA1LD_0RA0LC, cden, AIZ0_1RB1RB_1LC1RB_1RA1LD_0RA0LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  rewrite H1. cbn [rep app]. rewrite <- ?app_assoc. cbn [app].
  rewrite ?app_nil_r. reflexivity.
Qed.

Lemma genz_1RB1RB_1LC1RB_1RA1LD_0RA0LC : forall v q0, cview v = (0%nat, Some q0) ->
  lift (cden (Ip q0 ++ [S0;S1;S1]) [] 0 AIZ1_1RB1RB_1LC1RB_1RA1LD_0RA0LC) = lift (Cin (Pos.succ v)).
Proof.
  intros v q0 E. destruct (ILCounter.cview_some_I v 0 q0 E) as (_ & H2).
  unfold Cin_1RB1RB_1LC1RB_1RA1LD_0RA0LC, cden, AIZ1_1RB1RB_1LC1RB_1RA1LD_0RA0LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  cbn [rep app]. rewrite ?app_nil_r.
  rewrite H2. first [ reflexivity
        | cbn [rep app]; rewrite <- ?app_assoc; cbn [app];
          rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gsnp_1RB1RB_1LC1RB_1RA1LD_0RA0LC : forall v i q0, cview v = (S i, Some q0) ->
  Cin v = cden (Ip q0 ++ [S0;S1;S1]) [] i AIP0_1RB1RB_1LC1RB_1RA1LD_0RA0LC.
Proof.
  intros v i q0 E. destruct (ILCounter.cview_some_I v (S i) q0 E) as (H1 & _).
  unfold Cin_1RB1RB_1LC1RB_1RA1LD_0RA0LC, cden, AIP0_1RB1RB_1LC1RB_1RA1LD_0RA0LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  rewrite H1. cbn [rep app]. rewrite <- ?app_assoc. cbn [app].
  rewrite ?app_nil_r. reflexivity.
Qed.

Lemma genp_1RB1RB_1LC1RB_1RA1LD_0RA0LC : forall v i q0, cview v = (S i, Some q0) ->
  lift (cden (Ip q0 ++ [S0;S1;S1]) [] i AIP1_1RB1RB_1LC1RB_1RA1LD_0RA0LC) = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E. destruct (ILCounter.cview_some_I v (S i) q0 E) as (_ & H2).
  unfold Cin_1RB1RB_1LC1RB_1RA1LD_0RA0LC, cden, AIP1_1RB1RB_1LC1RB_1RA1LD_0RA0LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  rewrite H2. cbn [rep app]. rewrite <- ?app_assoc. cbn [app].
  rewrite ?app_nil_r. reflexivity.
Qed.

Lemma lapin_1RB1RB_1LC1RB_1RA1LD_0RA0LC : forall v i q0, cview v = (i, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cin v) = Some c'
               /\ lift c' = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E. destruct i as [|i'].
  - exists (0 * 0 + 4), (cden (Ip q0 ++ [S0;S1;S1]) [] 0 AIZ1_1RB1RB_1LC1RB_1RA1LD_0RA0LC).
    split; [lia|]. split; [| exact (genz_1RB1RB_1LC1RB_1RA1LD_0RA0LC v q0 E)].
    rewrite (gsnz_1RB1RB_1LC1RB_1RA1LD_0RA0LC v q0 E).
    exact (srun_sound tm false true chnz_1RB1RB_1LC1RB_1RA1LD_0RA0LC AIZ0_1RB1RB_1LC1RB_1RA1LD_0RA0LC AIZ1_1RB1RB_1LC1RB_1RA1LD_0RA0LC 0 4
             run_innerz_1RB1RB_1LC1RB_1RA1LD_0RA0LC (Ip q0 ++ [S0;S1;S1]) [] 0
             ltac:(discriminate) ltac:(reflexivity)).
  - exists (4 * i' + 8), (cden (Ip q0 ++ [S0;S1;S1]) [] i' AIP1_1RB1RB_1LC1RB_1RA1LD_0RA0LC).
    split; [lia|]. split; [| exact (genp_1RB1RB_1LC1RB_1RA1LD_0RA0LC v i' q0 E)].
    rewrite (gsnp_1RB1RB_1LC1RB_1RA1LD_0RA0LC v i' q0 E).
    exact (srun_sound tm false true chnp_1RB1RB_1LC1RB_1RA1LD_0RA0LC AIP0_1RB1RB_1LC1RB_1RA1LD_0RA0LC AIP1_1RB1RB_1LC1RB_1RA1LD_0RA0LC 4 8
             run_innerp_1RB1RB_1LC1RB_1RA1LD_0RA0LC (Ip q0 ++ [S0;S1;S1]) [] i'
             ltac:(discriminate) ltac:(reflexivity)).
Qed.

(** The boot lands on the OFFSET inner anchor up to 0/0 trailing
    blanks. *)
Lemma gbo_1RB1RB_1LC1RB_1RA1LD_0RA0LC : forall j, lift (cden [] [] j BB1_1RB1RB_1LC1RB_1RA1LD_0RA0LC) = lift (Cin (xO (xI (pow2 j)))).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_1RB1RB_1LC1RB_1RA1LD_0RA0LC = (StD, ([S1;S0;S1;S1] ++ rep [S1;S0] j ++ [S1;S0;S1;S1], S0, []))).
  { unfold cden, BB1_1RB1RB_1LC1RB_1RA1LD_0RA0LC, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (j + 1) by lia.
    rewrite rep_add. cbn [rep app]. rewrite ?app_nil_r.
    rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (xO (xI (pow2 j))) = (StD, ([S1;S0;S1;S1] ++ rep [S1;S0] j ++ [S1;S0;S1;S1], S0, []))).
  { unfold Cin_1RB1RB_1LC1RB_1RA1LD_0RA0LC. rewrite epre_1RB1RB_1LC1RB_1RA1LD_0RA0LC.
    first [ rewrite <- ?app_assoc; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  (* The offset boot can land one written blank past the anchor on EITHER
     side, and [lift] sees neither.  Strip it FIRST: [cbn [app]] flattens
     `w ++ [S0]` into one literal and destroys the shape
     [WTape.lift_app_blank_l] matches on. *)
  rewrite HD, HC. rewrite ?lift_app_blank_l.
  cbn [app]. rewrite <- ?app_assoc. cbn [app].
  rewrite ?lbl_1RB1RB_1LC1RB_1RA1LD_0RA0LC. rewrite ?lift_app_blank. reflexivity.
Qed.

(** The exit chain starts from the REPHASED fill (one unit cell rotated out
    front); [rrc_] bridges it back to the encoding's block frame. *)
Lemma gxi_1RB1RB_1LC1RB_1RA1LD_0RA0LC : forall j, Cin (fill (xO (xI (pow2 j)))) = cden [] [] j BE0_1RB1RB_1LC1RB_1RA1LD_0RA0LC.
Proof.
  intro j.
  assert (Hf : fill (xO (xI (pow2 j))) = fill (pow2 (S (S j))))
    by (cbn [pow2 fill]; reflexivity).
  rewrite Hf.
  destruct (ILCounter.cview_none_I (fill (pow2 (S (S j)))) (S (S j))
              (cview_fill_pow2 (S (S j)))) as (H1 & _).
  unfold Cin_1RB1RB_1LC1RB_1RA1LD_0RA0LC, cden, BE0_1RB1RB_1LC1RB_1RA1LD_0RA0LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 1) with (S j) by lia.
  replace (0 * j + 0) with 0 by lia.
  rewrite H1.
  cbn [app]. rewrite <- ?app_assoc. cbn [app].
  rewrite (rrc_1RB1RB_1LC1RB_1RA1LD_0RA0LC S1 [S1] (S j)).
  cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
  reflexivity.
Qed.

(** The interior lap, restated up to [lift] -- what [vis_via_ovf_lift] and
    [vis_via_fill] consume. *)
Lemma lapil_1RB1RB_1LC1RB_1RA1LD_0RA0LC : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. intros p j q0 E. destruct (lapi_1RB1RB_1LC1RB_1RA1LD_0RA0LC p j q0 E) as (n & Hn & Hr).
  exists n, (Cc (Pos.succ p)).
  split; [exact Hn | split; [exact Hr | reflexivity]]. Qed.

(** [cview p = (1, None)] forces [p = 1], where the offset family's count is
    empty: the overflow lap at p = 1 is ONE CONCRETE run, checked the way the
    bootstrap lemma is. *)
Lemma lapo0_1RB1RB_1LC1RB_1RA1LD_0RA0LC : exists n c', csteps tm n (Cc 1) = Some c'
    /\ lift c' = lift (Cc 2) /\ 0 < n.
Proof.
  exists 17.
  assert (H : match csteps tm 17 (Cc 1) with
              | Some c => ceqb c (Cc 2) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 17 (Cc 1)) as [c|] eqn:E0; [|discriminate].
  exists c. split; [reflexivity|]. split; [apply ceqb_lift; exact H | lia].
Qed.

(** The outer OVERFLOW branch.  The offset family's block count is one short
    of the outer index, so the branch REINDEXES: the generic route runs at
    [j = S j'] and [j = 0] is the concrete lap above. *)
Lemma lapo_1RB1RB_1LC1RB_1RA1LD_0RA0LC : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  destruct j as [|j'].
  - rewrite (cview_none_shape p 0 E). exact lapo0_1RB1RB_1LC1RB_1RA1LD_0RA0LC.
  - apply (nested_overflow_lift tm Cc Cin lapin_1RB1RB_1LC1RB_1RA1LD_0RA0LC p (xO (xI (pow2 j')))).
    + exists (4 * j' + 21), (cden [] [] j' BB1_1RB1RB_1LC1RB_1RA1LD_0RA0LC).
      split; [lia|]. split; [| exact (gbo_1RB1RB_1LC1RB_1RA1LD_0RA0LC j')].
      rewrite (gso_1RB1RB_1LC1RB_1RA1LD_0RA0LC p j' E).
      exact (srun_sound tm true true chb_1RB1RB_1LC1RB_1RA1LD_0RA0LC B0_1RB1RB_1LC1RB_1RA1LD_0RA0LC BB1_1RB1RB_1LC1RB_1RA1LD_0RA0LC 4 21
               run_boot_1RB1RB_1LC1RB_1RA1LD_0RA0LC [] [] j' ltac:(reflexivity) ltac:(reflexivity)).
    + exists (4 * j' + 12), (cden [] [] j' B1_1RB1RB_1LC1RB_1RA1LD_0RA0LC).
      split; [| exact (geo_1RB1RB_1LC1RB_1RA1LD_0RA0LC p j' E)].
      rewrite (gxi_1RB1RB_1LC1RB_1RA1LD_0RA0LC j').
      exact (srun_sound tm true true che_1RB1RB_1LC1RB_1RA1LD_0RA0LC BE0_1RB1RB_1LC1RB_1RA1LD_0RA0LC B1_1RB1RB_1LC1RB_1RA1LD_0RA0LC 4 12
