(** ** The lap *)

Lemma lap_1RB1RB_1LC1RD_0RA1LC_1RA0LC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
