  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB1RB_1LC1RD_0RA1LC_1RA0LC p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1RB_1LC1RD_0RA1LC_1RA0LC B0_1RB1RB_1LC1RD_0RA1LC_1RA0LC B1_1RB1RB_1LC1RD_0RA1LC_1RA0LC 6 10 p j' [] []).
    + exact run_ovf_1RB1RB_1LC1RD_0RA1LC_1RA0LC.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1RB_1LC1RD_0RA1LC_1RA0LC p j' E).
    + exact (geo_1RB1RB_1LC1RD_0RA1LC_1RA0LC p j' E).
    + lia.
