Lemma fireo_1RB1RB_1LC1RD_0RA1LC_1RA0LC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1RB_1LC1RD_0RA1LC_1RA0LC = Some t ->
