    rewrite (gso_1RB1RB_1LC1RD_0RB1LC_1RA0LC p j E).
    exact (srun_sound tm true true chb_1RB1RB_1LC1RD_0RB1LC_1RA0LC B0_1RB1RB_1LC1RD_0RB1LC_1RA0LC BB1_1RB1RB_1LC1RD_0RB1LC_1RA0LC 6 4
             run_boot_1RB1RB_1LC1RD_0RB1LC_1RA0LC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (6 * j + 14), (cden [] [] j B1_1RB1RB_1LC1RD_0RB1LC_1RA0LC).
    split; [| exact (geo_1RB1RB_1LC1RD_0RB1LC_1RA0LC p j E)].
    rewrite (gxi_1RB1RB_1LC1RD_0RB1LC_1RA0LC j).
    exact (srun_sound tm true true che_1RB1RB_1LC1RD_0RB1LC_1RA0LC BE0_1RB1RB_1LC1RD_0RB1LC_1RA0LC B1_1RB1RB_1LC1RD_0RB1LC_1RA0LC 6 14
             run_exit_1RB1RB_1LC1RD_0RB1LC_1RA0LC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.

(** A state firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma visx_1RB1RB_1LC1RD_0RB1LC_1RA0LC : forall (l : list lstep) (q : St),
  srun_st tm true true l BE0_1RB1RB_1LC1RD_0RB1LC_1RA0LC = Some q ->
