  intros l q Hst p j E.
  apply (vis_via_fill tm Cc Cin lapin_1RB1RB_1LC1RD_0RB1LC_1RA0LC q p (pow2 j)).
  - exists (6 * j + 4), (cden [] [] j BB1_1RB1RB_1LC1RD_0RB1LC_1RA0LC). split;
      [| exact (gbo_1RB1RB_1LC1RD_0RB1LC_1RA0LC j)].
