Lemma firex_1RB1RB_1LC1RD_0RB1LC_1RA0LC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_1RB1RB_1LC1RD_0RB1LC_1RA0LC = Some t ->
