(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB1RB_1LC1RD_0RD0LC_1LB0RA : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_101_111_11 q0 ++ [S0]) [] j A0_1RB1RB_1LC1RD_0RD0LC_1LB0RA.
