(** The lap ends on [S0] where the anchor has [] -- one trailing blank,
    which [lift] cannot see. *)
Lemma gei_1RB1RB_1LC1RD_0RD0LC_1LB0RA : forall p j q0, cview p = (j, Some q0) ->
  lift (cden (Ap_Alph_101_111_11 q0 ++ [S0]) [] j A1_1RB1RB_1LC1RD_0RD0LC_1LB0RA) = lift (Cc (Pos.succ p)).
