    apply (lap_of_run tm Cc true true cho_1RB1RB_1RC0LD_1LB1RA_0RB1LD B0_1RB1RB_1RC0LD_1LB1RA_0RB1LD B1_1RB1RB_1RC0LD_1LB1RA_0RB1LD 6 18 p j' [] []).
