  apply (nested_overflow_lift tm Cc Cin lapin_1RB1RB_1RC0LD_1LD1RA_0RA1LD p (pow2 j)).
  - exists (6 * j + 4), (cden [] [] j BB1_1RB1RB_1RC0LD_1LD1RA_0RA1LD).
    split; [lia|]. split; [| exact (gbo_1RB1RB_1RC0LD_1LD1RA_0RA1LD j)].
    rewrite (gso_1RB1RB_1RC0LD_1LD1RA_0RA1LD p j E).
    exact (srun_sound tm true true chb_1RB1RB_1RC0LD_1LD1RA_0RA1LD B0_1RB1RB_1RC0LD_1LD1RA_0RA1LD BB1_1RB1RB_1RC0LD_1LD1RA_0RA1LD 6 4
             run_boot_1RB1RB_1RC0LD_1LD1RA_0RA1LD [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (6 * j + 12), (cden [] [] j B1_1RB1RB_1RC0LD_1LD1RA_0RA1LD).
    split; [| exact (geo_1RB1RB_1RC0LD_1LD1RA_0RA1LD p j E)].
    rewrite (gxi_1RB1RB_1RC0LD_1LD1RA_0RA1LD j).
    exact (srun_sound tm true true che_1RB1RB_1RC0LD_1LD1RA_0RA1LD BE0_1RB1RB_1RC0LD_1LD1RA_0RA1LD B1_1RB1RB_1RC0LD_1LD1RA_0RA1LD 6 12
             run_exit_1RB1RB_1RC0LD_1LD1RA_0RA1LD [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.

(** A state firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma visx_1RB1RB_1RC0LD_1LD1RA_0RA1LD : forall (l : list lstep) (q : St),
  srun_st tm true true l BE0_1RB1RB_1RC0LD_1LD1RA_0RA1LD = Some q ->
