  apply (fire_of_run_instr tm Cc true true l B0_1RB1RB_1RC0LD_1LD1RA_0RA1LD p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1RB_1RC0LD_1LD1RA_0RA1LD p j E)].
Qed.


(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma firex_1RB1RB_1RC0LD_1LD1RA_0RA1LD : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_1RB1RB_1RC0LD_1LD1RA_0RA1LD = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ instr_of e = t.
