  apply (fire_via_fill tm Cc Cin lapin_1RB1RB_1RC0LD_1LD1RA_0RA1LD t p (pow2 j)).
  - exists (6 * j + 4), (cden [] [] j BB1_1RB1RB_1RC0LD_1LD1RA_0RA1LD). split;
      [| exact (gbo_1RB1RB_1RC0LD_1LD1RA_0RA1LD j)].
    rewrite (gso_1RB1RB_1RC0LD_1LD1RA_0RA1LD p j E).
    exact (srun_sound tm true true chb_1RB1RB_1RC0LD_1LD1RA_0RA1LD B0_1RB1RB_1RC0LD_1LD1RA_0RA1LD BB1_1RB1RB_1RC0LD_1LD1RA_0RA1LD 6 4
             run_boot_1RB1RB_1RC0LD_1LD1RA_0RA1LD [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (fire_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (fire_of_run_instr tm (fun _ : positive => Cin (fill (pow2 j)))
                      true true l BE0_1RB1RB_1RC0LD_1LD1RA_0RA1LD xH j [] []);
      [exact Hst | reflexivity | reflexivity | exact (gxi_1RB1RB_1RC0LD_1LD1RA_0RA1LD j)].
