(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB1RB_1RC0LD_1LD1RA_0RA1LD : forall t, ~ In t pins_1RB1RB_1RC0LD_1LD1RA_0RA1LD ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB1RB_1RC0LD_1LD1RA_0RA1LD.
  destruct t as [q b]; destruct q, b.
  - (* A0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1RB_1RC0LD_1LD1RA_0RA1LD (StA, S0)).
    intros p1 j1 E1.
    exact (firex_1RB1RB_1RC0LD_1LD1RA_0RA1LD [SRotL 1; SWin 1; SCycL 3 0; SWin 2; SWinL 1] (StA, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_1RB1RB_1RC0LD_1LD1RA_0RA1LD
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* B0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1RB_1RC0LD_1LD1RA_0RA1LD (StB, S0)).
    intros p1 j1 E1.
    exact (firex_1RB1RB_1RC0LD_1LD1RA_0RA1LD [SRotL 1; SWin 1; SCycL 3 0; SWin 1] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB1RB_1RC0LD_1LD1RA_0RA1LD
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 1]).
    vm_compute; reflexivity.
  - (* C0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1RB_1RC0LD_1LD1RA_0RA1LD (StC, S0)).
    intros p1 j1 E1.
    exact (firex_1RB1RB_1RC0LD_1LD1RA_0RA1LD [SRotL 1; SWin 1; SCycL 3 0; SWin 2; SWinL 3] (StC, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1RB_1RC0LD_1LD1RA_0RA1LD (StC, S1)).
    intros p1 j1 E1.
    exact (firex_1RB1RB_1RC0LD_1LD1RA_0RA1LD [SRotL 1; SWin 1; SCycL 3 0; SWin 2] (StC, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB1RB_1RC0LD_1LD1RA_0RA1LD
      with (l := []).
    vm_compute; reflexivity.
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_1RB1RB_1RC0LD_1LD1RA_0RA1LD
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 2]).
    vm_compute; reflexivity.
Qed.

Theorem nqhtrm_1RB1RB_1RC0LD_1LD1RA_0RA1LD : NeverQuasiHaltsTr tmm_1RB1RB_1RC0LD_1LD1RA_0RA1LD.
Proof.
  apply (glue_neverqhtr tmm_1RB1RB_1RC0LD_1LD1RA_0RA1LD pins_1RB1RB_1RC0LD_1LD1RA_0RA1LD Cc 1).
  - exact boot_1RB1RB_1RC0LD_1LD1RA_0RA1LD.
  - intros p _. apply lap_1RB1RB_1RC0LD_1LD1RA_0RA1LD.
