Lemma fire_1RB1RB_1RC0RA_1LD1RB_1LA0LD : forall t, ~ In t pins_1RB1RB_1RC0RA_1LD1RB_1LA0LD ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
