(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_1RB1RB_1RC0RA_1LD1RC_1LA0LD : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Kp q0 ++ [S0]) [] 0 Z0_1RB1RB_1RC0RA_1LD1RC_1LA0LD /\
  cden (Kp q0 ++ [S0]) [] 0 Z1_1RB1RB_1RC0RA_1LD1RC_1LA0LD = Cc (Pos.succ p).
Proof.
