  unfold Cc_1RB1RB_1RC0RA_1LD1RC_1LA0LD, cden, Z0_1RB1RB_1RC0RA_1LD1RC_1LA0LD, Z1_1RB1RB_1RC0RA_1LD1RC_1LA0LD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gp_1RB1RB_1RC0RA_1LD1RC_1LA0LD : forall p j q0, cview p = (S j, Some q0) ->
  Cc p = cden (Kp q0 ++ [S0]) [] j P0_1RB1RB_1RC0RA_1LD1RC_1LA0LD /\
  cden (Kp q0 ++ [S0]) [] j P1_1RB1RB_1RC0RA_1LD1RC_1LA0LD = Cc (Pos.succ p).
