    exists (0 * 0 + 8). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chz_1RB1RB_1RC0RA_1LD1RC_1LA0LD Z0_1RB1RB_1RC0RA_1LD1RC_1LA0LD Z1_1RB1RB_1RC0RA_1LD1RC_1LA0LD 0 8
               run_z_1RB1RB_1RC0RA_1LD1RC_1LA0LD (Kp q0 ++ [S0]) [] 0
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
  - destruct (gp_1RB1RB_1RC0RA_1LD1RC_1LA0LD p j' q0 E) as (HA & HB).
    exists (2 * j' + 10). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_1RB1RB_1RC0RA_1LD1RC_1LA0LD P0_1RB1RB_1RC0RA_1LD1RC_1LA0LD P1_1RB1RB_1RC0RA_1LD1RC_1LA0LD 2 10
