    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB1RB_1RC0RB_1LD1RA_1LA0LD
      with (l := [SWin 2; SRotL 1; SWin 1; SCycL 3 0; SWin 1]).
    vm_compute; reflexivity.
