(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_1RB1RB_1RC1RA_1LC1LD_0RA0LD : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Dp q0 ++ [S0]) [] 0 Z0_1RB1RB_1RC1RA_1LC1LD_0RA0LD /\
  lift (cden (Dp q0 ++ [S0]) [] 0 Z1_1RB1RB_1RC1RA_1LC1LD_0RA0LD) = lift (Cc (Pos.succ p)).
