Lemma gsi_1RB1RC_0LA0LD_1LB0RA_1RA1LD : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j A0_1RB1RC_0LA0LD_1LB0RA_1RA1LD.
