Lemma geo_1RB1RC_0LA0LD_1LB0RA_1RA1LD : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1RC_0LA0LD_1LB0RA_1RA1LD) = lift (Cc (Pos.succ p)).
