(** ** The lap *)

Lemma lap_1RB1RC_0LA0LD_1LB0RA_1RA1LD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
