  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB1RC_0LA0LD_1LB0RA_1RA1LD p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1RC_0LA0LD_1LB0RA_1RA1LD B0_1RB1RC_0LA0LD_1LB0RA_1RA1LD B1_1RB1RC_0LA0LD_1LB0RA_1RA1LD 4 17 p j' [] []).
    + exact run_ovf_1RB1RC_0LA0LD_1LB0RA_1RA1LD.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1RC_0LA0LD_1LB0RA_1RA1LD p j' E).
    + exact (geo_1RB1RC_0LA0LD_1LB0RA_1RA1LD p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma boot_1RB1RC_0LA0LD_1LB0RA_1RA1LD : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 18.
  assert (H : match csteps tm 18 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 18 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

