Lemma fire_1RB1RC_0LA0LD_1LB0RA_1RA1LD : forall t, ~ In t pins_1RB1RC_0LA0LD_1LB0RA_1RA1LD ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
