  apply (nested_overflow_lift tm Cc Cin lapin_1RB1RC_0LA0RA_0LD1RB_1RA1LD p (pow2 j)).
  - exists (6 * j + 6), (cden [] [] j BB1_1RB1RC_0LA0RA_0LD1RB_1RA1LD).
    split; [lia|]. split; [| exact (gbo_1RB1RC_0LA0RA_0LD1RB_1RA1LD j)].
    rewrite (gso_1RB1RC_0LA0RA_0LD1RB_1RA1LD p j E).
    exact (srun_sound tm true true chb_1RB1RC_0LA0RA_0LD1RB_1RA1LD B0_1RB1RC_0LA0RA_0LD1RB_1RA1LD BB1_1RB1RC_0LA0RA_0LD1RB_1RA1LD 6 6
             run_boot_1RB1RC_0LA0RA_0LD1RB_1RA1LD [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (6 * j + 13), (cden [] [] j B1_1RB1RC_0LA0RA_0LD1RB_1RA1LD).
    split; [| exact (geo_1RB1RC_0LA0RA_0LD1RB_1RA1LD p j E)].
    rewrite (gxi_1RB1RC_0LA0RA_0LD1RB_1RA1LD j).
    exact (srun_sound tm true true che_1RB1RC_0LA0RA_0LD1RB_1RA1LD BE0_1RB1RC_0LA0RA_0LD1RB_1RA1LD B1_1RB1RC_0LA0RA_0LD1RB_1RA1LD 6 13
             run_exit_1RB1RC_0LA0RA_0LD1RB_1RA1LD [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_1RB1RC_0LA0RA_0LD1RB_1RA1LD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB1RC_0LA0RA_0LD1RB_1RA1LD p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_1RB1RC_0LA0RA_0LD1RB_1RA1LD p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_1RB1RC_0LA0RA_0LD1RB_1RA1LD : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 7.
  assert (H : match csteps tm 7 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 7 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
