Lemma gsi_1RB1RC_0LA0RB_0LD1LD_1RA1LC : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Dp q0 ++ [S0]) [] j A0_1RB1RC_0LA0RB_0LD1LD_1RA1LC.
