Lemma geo_1RB1RC_0LA0RC_1LD0LD_0RB1LA : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1RC_0LA0RC_1LD0LD_0RB1LA) = lift (Cc (Pos.succ p)).
