      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StB, ((rep [S0] (S j) ++ [S1]) ++ [S0], S0, []))).
  { unfold Cc_1RB1RC_0LA0RC_1LD0LD_0RB1LA. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lbl_1RB1RC_0LA0RC_1LD0LD_0RB1LA. reflexivity.
