Lemma lapi_1RB1RC_0LA1RA_0LD0RB_1RB1LD : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
