Lemma gsi_1RB1RC_0LA1RA_1LC0LD_0RA0LC : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_00_10_1 q0 ++ [S0]) [] j A0_1RB1RC_0LA1RA_1LC0LD_0RA0LC.
